        /// <summary>
        /// This function is used to return all the late fee configuration.
        /// </summary>
        /// <param name="sStdID"></param>
        /// <param name="sSchoolID"></param>
        /// <param name="sAcadID"></param>
        /// <returns></returns>
        public static List<LateFeeConfiguration> GetStandardwiseLateFeeDueDatesMasterDetails(string asStdID, string asSchoolID, string asAcademicYearID, out List<LateFeeTypes> alstLateFeeTypes, out List<LateFeeDetails> alstLateFeeDetails)
        {
            var lstLateFeeConfiguration = new List<LateFeeConfiguration>();
            alstLateFeeDetails = new List<LateFeeDetails>();
            using (var oSQLServerDbUtility = new SQLServerDbUtility())
            {
                oSQLServerDbUtility.AddParameter("SchoolId", asSchoolID, SqlDbType.Int);
                oSQLServerDbUtility.AddParameter("AcademicYearId", asAcademicYearID, SqlDbType.Int);
                oSQLServerDbUtility.AddParameter("StandardId", asStdID, SqlDbType.Int);

                using (SqlDataReader oReader = oSQLServerDbUtility.ExecuteStoredProcedureAndGetresult("usp_GetFeeTypewiseLateFeeConfigDetails"))
                {                 
                    lstLateFeeConfiguration=FillFeeTypesWithIntervals(oReader);
                    alstLateFeeTypes=FillFeeTypes(oReader);

                    if (oReader.NextResult())
                     alstLateFeeDetails = FillLateFeeDetails(oReader);
                }
            }

            return lstLateFeeConfiguration;
        }

        /// <summary>
        /// This method is used to load late fee details.
        /// </summary>
        /// <param name="aoReader"></param>
        /// <returns></returns>
        private static List<LateFeeDetails> FillLateFeeDetails(SqlDataReader aoReader)
        {
            List<LateFeeDetails> lstLateFeeDetails = new List<LateFeeDetails>();
            while (aoReader.Read())
            {
                lstLateFeeDetails.Add(
                        new LateFeeDetails
                        {
                            Amount = Convert.ToInt32(aoReader["Amount"]),
                            ExcludeHolidays = Convert.ToBoolean(aoReader["ExcludeHolidays"]),
                            ExcludeWeekends = Convert.ToBoolean(aoReader["ExcludeWeekends"]),
                            Id = Convert.ToInt32(aoReader["Id"]),
                            LateFeeId = Convert.ToInt32(aoReader["LateFeeId"]),
                            LateFeePerTypeId = Convert.ToInt32(aoReader["IntervalId"]),
                            RepeatCount = Convert.ToInt32(aoReader["RepeatCount"]),
                            SortOrder = Convert.ToInt32(aoReader["SortOrder"]),
                            FeeTypeId = Convert.ToInt32(aoReader["FeeTypeId"]),
                            ValueForType = Convert.ToInt32(aoReader["Days"])
                        }
                    );
            }
            return lstLateFeeDetails;
        }

        /// <summary>
        /// This function is used to return all the late fee configuration.
        /// </summary>
        /// <param name="oReader"></param>
        /// <returns></returns>
        private static List<FeeTypeInterval> FillIntervals(SqlDataReader aoReader)
        {
            var lstDueDateDetails = new List<FeeTypeInterval>();
            while (aoReader.Read())
                lstDueDateDetails.Add(new FeeTypeInterval
                {
                    StandardwiseFeeTypeId = aoReader["StandardwiseFeeTypeId"].ToInt(),
                    IntervalName = aoReader["IntervalName"].ToString(),
                    Due_Date = aoReader["DueDate"].ToDateTime(),
                    DueDateDetailsId = aoReader["DueDateDetailsId"].ToInt(),
                    IntervalStartDate = aoReader["IntervalStartDate"].ToDateTime(),
                    IntervalEndDate = aoReader["IntervalEndDate"].ToDateTime()
                });

            return lstDueDateDetails;
        }

        private static List<LateFeeConfiguration> FillFeeTypesWithIntervals(SqlDataReader aoReader)
        {
            List<LateFeeConfiguration> lstLateFeeConfigurations = new List<LateFeeConfiguration>();
            List<FeeTypeInterval> lstFeeTypeIntervals = FillIntervals(aoReader);
            if (aoReader.NextResult())
                while (aoReader.Read())
                {
                    int iStandardwiseFeeTypeId = aoReader["StandardwiseFeeTypeId"].ToInt();
                    LateFeeConfiguration oLateFeeConfiguration = new LateFeeConfiguration
                    {
                        Fee_Type = aoReader["Fee_Type"].ToString(),
                        Fee_Type_Id = aoReader["Fee_Type_Id"].ToInt(),
                        Late_Fee = aoReader["Late_Fee"].ToString(),
                        School_Id = aoReader["School_Id"].ToInt(),
                        Academic_Year_Id = aoReader["Academic_Year_Id"].ToInt(),
                        Standard_Id = aoReader["Standard_Id"].ToInt(),
                        StandardwiseFeeTypeId = aoReader["StandardwiseFeeTypeId"].ToInt(),
                        Interval = aoReader["Interval"].ToInt(),                                    
                        LateFeePerTypeId = aoReader["LateFeePerTypeId"].ToInt(),
                        ValueForType = aoReader["ValueForType"].ToInt(),
                        Original_Fee_Type_Id = aoReader["Original_Fee_Type_Id"].ToInt(),
                        IsStudentFeeCount = aoReader["IsStudentFeeCount"].ToInt(),
                        DeactivateUser = aoReader["DeactivateUser"].ToInt(),
                        ThresholdMonths = aoReader["ThresholdMonths"].ToInt(),
                        ThresholdDays = aoReader["ThresholdDays"].ToInt(),
                        ReminderDays = aoReader["ReminderDays"].ToInt(),
                        ReminderInterval = aoReader["ReminderInterval"].ToInt(),
                        ReminderSMS = aoReader["ReminderSMS"].ToInt(),
                        IsConfigured = aoReader["IsConfigured"].ToInt(),
                        LateFeeIntervals = lstFeeTypeIntervals.Where(Id => Id.StandardwiseFeeTypeId == iStandardwiseFeeTypeId).ToList()
                    };
                    lstLateFeeConfigurations.Add(oLateFeeConfiguration);
                        
                }
            return lstLateFeeConfigurations;
        }

        /// <summary>
        /// This function initializes property of late fee types.
        /// </summary>
        /// <param name="oReader"></param>
        private static List<LateFeeTypes> FillFeeTypes(SqlDataReader aoReader)
        {
            List<LateFeeTypes> lstLateFeeTypes = new List<LateFeeTypes>();
            if (aoReader.NextResult())
                while (aoReader.Read())
                {
                    LateFeeTypes oLateFeeTypes = new LateFeeTypes
                    {
                        LateFeeTypeId = aoReader["LateFeeTypeId"].ToInt(),
                        LateFeeType = aoReader["LateFeeType"].ToString()
                    };
                    lstLateFeeTypes.Add(oLateFeeTypes);
                }

            return lstLateFeeTypes;
        }

		#endregion -- PUBLIC METHOD(s) --
	}
